package com.safarilanka.controller;
import com.safarilanka.model.*; import com.safarilanka.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/reports")
public class ReportController {
 private final BookingRepository bookings; private final PaymentRepository payments; private final RefundRequestRepository refunds; private final PermitRepository permits; private final TripAssignmentRepository assignments; private final VehicleRepository vehicles; public ReportController(BookingRepository b,PaymentRepository p,RefundRequestRepository r,PermitRepository pe,TripAssignmentRepository a,VehicleRepository v){bookings=b;payments=p;refunds=r;permits=pe;assignments=a;vehicles=v;}
 @GetMapping("/finance") @PreAuthorize("hasAnyRole('FINANCE_MANAGER','SYSTEM_ADMIN')") public Map<String,Object> finance(){BigDecimal revenue=payments.findAll().stream().filter(p->p.getStatus()==PaymentStatus.PAID).map(Payment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal refunded=payments.findAll().stream().filter(p->p.getStatus()==PaymentStatus.REFUNDED).map(Payment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("successfulPayments",payments.findAll().stream().filter(p->p.getStatus()==PaymentStatus.PAID).count(),"revenue",revenue,"refunded",refunded,"pendingRefunds",refunds.findAll().stream().filter(r->r.getStatus()==RefundStatus.PENDING).count());}
 @GetMapping("/operations") @PreAuthorize("hasAnyRole('SAFARI_OPERATOR','PARK_OFFICER','SYSTEM_ADMIN')") public Map<String,Object> ops(){return Map.of("bookings",bookings.count(),"confirmed",bookings.findAll().stream().filter(b->b.getBookingStatus()==BookingStatus.CONFIRMED).count(),"assignments",assignments.count(),"vehicles",vehicles.count(),"pendingPermits",permits.findAll().stream().filter(p->p.getStatus()==PermitStatus.PENDING).count(),"checkedIn",permits.findAll().stream().filter(p->p.getStatus()==PermitStatus.CHECKED_IN).count());}
}
